176	// assertHeaderConflict requires the exact CLI surface of a trusted-header
177	// conflict: exit code 16, a stderr line naming the conflict category together
178	// with chain, height, the submitted root and the accepted root, and nothing on
179	// stdout (in particular no "stored header" success line).
180	func assertHeaderConflict(t *testing.T, r cliResult, chain string, height int64, submitted, accepted string) {
181		t.Helper()
182		if r.code != 16 {
183			t.Fatalf("want exit code 16, got %d (stdout=%q stderr=%q)", r.code, r.stdout, r.stderr)
184		}
185		if r.stdout != "" {
186			t.Fatalf("a rejected header must not print a success line on stdout: %q", r.stdout)
187		}
188		for _, want := range []string{
189			"trusted header conflict",
190			`chain "` + chain + `"`,
191			"height " + strconv.FormatInt(height, 10),
192			"submitted root " + strconv.Quote(submitted),
193			"conflicts with accepted root " + strconv.Quote(accepted),
194		} {
195			if !strings.Contains(r.stderr, want) {
196				t.Fatalf("stderr missing %q:\n%s", want, r.stderr)
197			}
198		}
199	}
